1	//! Versioned, disposable provider interpretation of an explicitly selected body.
2	//! Provider roles and protocol outcomes are claims. No network, execution, grant
3	//! validation, persistence or capture-completeness certificate is provided.
4	use crate::{
5	    evidence_assembly::{Input, Payload, SourceSpan, Stream},
6	    evidence_capture::Event,
7	    evidence_reconstruction::{self as decode, Decoded, Unique},
8	};
9	use serde_json::Value;
10	use std::{
11	    collections::BTreeMap,
12	    ops::Range,
13	    sync::{
14	        atomic::{AtomicBool, Ordering},
15	        Arc,
16	    },
17	    time::{Duration, Instant},
18	};
19	
20	pub const VERSION: &str = "kan-anthropic-messages/1";
21	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
22	pub enum Format {
23	    Request,
24	    Response,
25	    Sse,
26	}
27	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
28	pub enum Kind {
29	    Context,
30	    System,
31	    Text,
32	    ToolUse,
33	    ToolResult,
34	    Thinking,
35	    Attachment,
36	    ToolFragment,
37	    Protocol,
38	    Error,
39	    Unsupported,
40	    Malformed,
41	    Truncated,
42	}
43	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
44	pub enum Issue {
45	    Shape,
46	    EventName,
47	    Sequence,
48	    BlockIndex,
49	    DeltaType,
50	    ToolJson,
51	    Unknown,
52	}
53	#[derive(Debug)]
54	pub struct Item {
55	    pub kind: Kind,
56	    /// Enclosing assembled-body bytes, exclusive end. Semantic attribution is
57	    /// coarse: this is never claimed to be the exact JSON string token range.
58	    pub region: Range<usize>,
59	    pub coarse: bool,
60	    pub role: Option<String>,
61	    pub index: Option<u64>,
62	    pub text: Option<String>,
63	    /// Location in Document.json for non-streamed input; JSON pointer escaping
64	    /// is unnecessary because this adapter generates only fixed keys/indices.
65	    pub pointer: Option<String>,
66	    /// Complete event JSON, including fields this adapter does not interpret.
67	    pub event: Option<Value>,
68	    pub issues: Vec<Issue>,
69	}
70	#[derive(Debug)]
71	pub struct Document {
72	    pub format: Format,
73	    pub json: Option<Value>,
74	    pub items: Vec<Item>,
75	    /// A coherent protocol stop was observed, not complete traffic capture.
76	    /// False for request/JSON response: those have no SSE stop observation.
77	    pub coherent_stop_observed: bool,
78	    pub scanned_bytes: u64,
79	    pub output_bytes: u64,
80	}
81	#[derive(Clone)]
82	pub struct Limits {
83	    pub input_bytes: usize,
84	    pub items: usize,
85	    /// Cumulative encoded JSON and copied text/data bytes, not exact RSS.
86	    pub output_bytes: u64,
87	    /// SSE line acquisition, JSON parsing and source decode/comparison bytes.
88	    /// This is accounting for those passes, not every CPU instruction.
89	    pub scan_bytes: u64,
90	    pub citations: usize,
91	    pub duration: Duration,
92	    pub cancelled: Arc<AtomicBool>,
93	}
94	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
95	pub enum Error {
96	    #[error("provider interpretation budget exhausted: {0}")]
97	    Limit(&'static str),
98	    #[error("provider interpretation cancelled")]
99	    Cancelled,
100	    #[error("invalid source mapping")]
101	    Mapping,
102	}
103	type Result<T> = std::result::Result<T, Error>;
104	struct Work {
105	    limits: Limits,
106	    deadline: Instant,
107	    scan: u64,
108	    output: u64,
109	    items: usize,
110	}
111	impl Work {
112	    fn new(limits: Limits) -> Result<Self> {
113	        if limits.duration.is_zero() || limits.duration > Duration::from_secs(3600) {
114	            return Err(Error::Limit("duration"));
115	        }
116	        let deadline = Instant::now()
117	            .checked_add(limits.duration)
118	            .ok_or(Error::Limit("duration"))?;
119	        let w = Self {
120	            limits,
121	            deadline,
122	            scan: 0,
123	            output: 0,
124	            items: 0,
125	        };
126	        w.check()?;
127	        Ok(w)
128	    }
129	    fn check(&self) -> Result<()> {
130	        if self.limits.cancelled.load(Ordering::Relaxed) {
131	            return Err(Error::Cancelled);
132	        }
133	        if Instant::now() >= self.deadline {
134	            return Err(Error::Limit("duration"));
135	        }
136	        Ok(())
137	    }
138	    fn scan(&mut self, n: usize) -> Result<()> {
139	        self.check()?;
140	        self.scan = self
141	            .scan
142	            .checked_add(n as u64)
143	            .ok_or(Error::Limit("scan bytes"))?;
144	        if self.scan > self.limits.scan_bytes {
145	            return Err(Error::Limit("scan bytes"));
146	        }
147	        Ok(())
148	    }
149	    fn output(&mut self, n: usize) -> Result<()> {
150	        self.check()?;
151	        self.output = self
152	            .output
153	            .checked_add(n as u64)
154	            .ok_or(Error::Limit("output bytes"))?;
155	        if self.output > self.limits.output_bytes {
156	            return Err(Error::Limit("output bytes"));
157	        }
158	        Ok(())
159	    }
160	    fn item(&mut self) -> Result<()> {
161	        self.check()?;
162	        self.items = self.items.checked_add(1).ok_or(Error::Limit("items"))?;
163	        if self.items > self.limits.items {
164	            return Err(Error::Limit("items"));
165	        }
166	        Ok(())
167	    }
168	    fn string(&mut self, s: &str) -> Result<String> {
169	        self.output(s.len())?;
170	        Ok(s.into())
171	    }
172	}
173	fn item(kind: Kind, region: Range<usize>) -> Item {
174	    Item {
175	        kind,
176	        region,
177	        coarse: true,
178	        role: None,
179	        index: None,
180	        text: None,
181	        pointer: None,
182	        event: None,
183	        issues: vec![],
184	    }
185	}
186	fn push(out: &mut Vec<Item>, value: Item, w: &mut Work) -> Result<()> {
187	    w.item()?;
188	    out.push(value);
189	    Ok(())
190	}
191	fn strict(bytes: &[u8], w: &mut Work) -> Result<Option<Value>> {
192	    // Input bounds precede allocation, serde's recursion limit remains enabled.
193	    w.scan(bytes.len())?;
194	    w.output(bytes.len())?;
195	    let parsed = serde_json::from_slice::<Unique>(bytes).ok().map(|u| u.0);
196	    w.check()?;
197	    Ok(parsed)
198	}
199	fn block(
200	    value: &Value,
201	    pointer: String,
202	    role: Option<&str>,
203	    region: Range<usize>,
204	    out: &mut Vec<Item>,
205	    w: &mut Work,
206	) -> Result<()> {
207	    let (kind, text) = if let Some(s) = value.as_str() {
208	        (Kind::Text, Some(s))
209	    } else {
210	        match value.get("type").and_then(Value::as_str) {
211	            Some("text") => (Kind::Text, value.get("text").and_then(Value::as_str)),
212	            Some("thinking") => (
213	                Kind::Thinking,
214	                value.get("thinking").and_then(Value::as_str),
215	            ),
216	            Some("redacted_thinking") => (Kind::Thinking, None),
217	            Some("tool_use" | "server_tool_use") => {
218	                (Kind::ToolUse, value.get("name").and_then(Value::as_str))
219	            }
220	            Some("tool_result") => (
221	                Kind::ToolResult,
222	                value.get("content").and_then(Value::as_str),
223	            ),
224	            Some("image" | "document") => (Kind::Attachment, None),
225	            Some(_) => (Kind::Unsupported, None),
226	            None => (Kind::Malformed, None),
227	        }
228	    };
229	    let mut i = item(kind, region);
230	    i.pointer = Some(w.string(&pointer)?);
231	    i.role = role.map(|s| w.string(s)).transpose()?;
232	    i.text = text.map(|s| w.string(s)).transpose()?;
233	    if matches!(kind, Kind::Text | Kind::ToolUse) && text.is_none() {
234	        i.kind = Kind::Malformed;
235	        i.issues.push(Issue::Shape);
236	    }
237	    if kind == Kind::Unsupported {
238	        i.issues.push(Issue::Unknown);
239	    }
240	    push(out, i, w)
241	}
242	fn content(
243	    value: &Value,
244	    pointer: &str,
245	    role: Option<&str>,
246	    region: Range<usize>,
247	    out: &mut Vec<Item>,
248	    w: &mut Work,
249	) -> Result<()> {
250	    if let Some(values) = value.as_array() {
251	        for (n, v) in values.iter().enumerate() {
252	            w.check()?;
253	            block(v, format!("{pointer}/{n}"), role, region.clone(), out, w)?;
254	        }
255	    } else {
256	        block(value, pointer.into(), role, region, out, w)?;
257	    }
258	    Ok(())
259	}
260	fn json_body(bytes: &[u8], format: Format, doc: &mut Document, w: &mut Work) -> Result<()> {
261	    let Some(value) = strict(bytes, w)? else {
262	        return push(&mut doc.items, item(Kind::Malformed, 0..bytes.len()), w);
263	    };
264	    let region = 0..bytes.len();
265	    if !value.is_object() {
266	        push(&mut doc.items, item(Kind::Malformed, region), w)?;
267	        doc.json = Some(value);
268	        return Ok(());
269	    }
270	    // Always expose the root, preserving unknown fields and empty contents.
271	    let mut root = item(Kind::Protocol, region.clone());
272	    root.pointer = Some(String::new());
273	    push(&mut doc.items, root, w)?;
274	    if format == Format::Request {
275	        if let Some(system) = value.get("system") {
276	            let mut i = item(Kind::System, region.clone());
277	            i.pointer = Some(w.string("/system")?);
278	            push(&mut doc.items, i, w)?;
279	            content(
280	                system,
281	                "/system",
282	                Some("system"),
283	                region.clone(),
284	                &mut doc.items,
285	                w,
286	            )?;
287	        }
288	        if let Some(messages) = value.get("messages").and_then(Value::as_array) {
289	            for (n, message) in messages.iter().enumerate() {
290	                w.check()?;
291	                let role = message.get("role").and_then(Value::as_str);
292	                let mut i = item(Kind::Context, region.clone());
293	                i.pointer = Some(w.string(&format!("/messages/{n}"))?);
294	                i.role = role.map(|s| w.string(s)).transpose()?;
295	                if !matches!(role, Some("user" | "assistant")) {
296	                    i.issues.push(Issue::Shape);
297	                }
298	                push(&mut doc.items, i, w)?;
299	                if let Some(c) = message.get("content") {
300	                    content(
301	                        c,
302	                        &format!("/messages/{n}/content"),
303	                        role,
304	                        region.clone(),
305	                        &mut doc.items,
306	                        w,
307	                    )?;
308	                } else {
309	                    push(&mut doc.items, item(Kind::Malformed, region.clone()), w)?;
310	                }
311	            }
312	        } else {
313	            push(&mut doc.items, item(Kind::Malformed, region.clone()), w)?;
314	        }
315	    } else if value.get("type").and_then(Value::as_str) == Some("error") {
316	        let mut i = item(Kind::Error, region.clone());
317	        i.pointer = Some(w.string("/error")?);
318	        push(&mut doc.items, i, w)?;
319	    } else if value.get("type").and_then(Value::as_str) == Some("message") {
320	        let role = value.get("role").and_then(Value::as_str);
321	        if let Some(c) = value.get("content") {
322	            content(c, "/content", role, region, &mut doc.items, w)?;
323	        } else {
324	            push(&mut doc.items, item(Kind::Malformed, region), w)?;
325	        }
326	    } else {
327	        push(&mut doc.items, item(Kind::Unsupported, region), w)?;
328	    }
329	    doc.json = Some(value);
330	    Ok(())
331	}
332	#[derive(Clone, Copy, PartialEq, Eq)]
333	enum BlockKind {
334	    Text,
335	    Thinking,
336	    Tool,
337	    Unknown,
338	}
339	struct ActiveBlock {
340	    kind: BlockKind,
341	    stopped: bool,
342	    fragments: String,
343	    fragmented: bool,
344	}
345	#[derive(Default)]
346	struct State {
347	    started: bool,
348	    stopped: bool,
349	    delta: bool,
350	    invalid: bool,
351	    open_blocks: usize,
352	    blocks: BTreeMap<u64, ActiveBlock>,
353	}
354	fn event(
355	    value: Value,
356	    name: Option<&str>,
357	    region: Range<usize>,
358	    state: &mut State,
359	    w: &mut Work,
360	) -> Result<Item> {
361	    let mut i = item(Kind::Protocol, region);
362	    let typ = value.get("type").and_then(Value::as_str);
363	    if typ.is_none() || name.is_some_and(|n| Some(n) != typ) {
364	        i.issues.push(Issue::EventName);
365	    }
366	    let index = value.get("index").and_then(Value::as_u64);
367	    i.index = index;
368	    if state.stopped {
369	        i.issues.push(Issue::Sequence);
370	    }
371	    match typ {
372	        Some("message_start") => {
373	            if state.started {
374	                i.issues.push(Issue::Sequence);
375	            }
376	            state.started = true;
377	            let m = value.get("message");
378	            if m.and_then(|m| m.get("type")).and_then(Value::as_str) != Some("message")
379	                || m.and_then(|m| m.get("role")).and_then(Value::as_str) != Some("assistant")
380	                || !m
381	                    .and_then(|m| m.get("content"))
382	                    .and_then(Value::as_array)
383	                    .is_some_and(Vec::is_empty)
384	            {
385	                i.issues.push(Issue::Shape);
386	            }
387	        }
388	        Some("content_block_start") => {
389	            if !state.started || state.delta {
390	                i.issues.push(Issue::Sequence);
391	            }
392	            if let Some(index) = index {
393	                if let std::collections::btree_map::Entry::Vacant(entry) = state.blocks.entry(index)
394	                {
395	                    let b = value.get("content_block");
396	                    let kind = match b.and_then(|b| b.get("type")).and_then(Value::as_str) {
397	                        Some("text") => {
398	                            i.kind = Kind::Text;
399	                            BlockKind::Text
400	                        }
401	                        Some("thinking" | "redacted_thinking") => {
402	                            i.kind = Kind::Thinking;
403	                            BlockKind::Thinking
404	                        }
405	                        Some("tool_use" | "server_tool_use") => {
406	                            i.kind = Kind::ToolUse;
407	                            BlockKind::Tool
408	                        }
409	                        _ => {
410	                            i.kind = Kind::Unsupported;
411	                            i.issues.push(Issue::Unknown);
412	                            BlockKind::Unknown
413	                        }
414	                    };
415	                    let key = match kind {
416	                        BlockKind::Text => "text",
417	                        BlockKind::Thinking => "thinking",
418	                        BlockKind::Tool => "name",
419	                        BlockKind::Unknown => "",
420	                    };
421	                    i.text = b
422	                        .and_then(|b| b.get(key))
423	                        .and_then(Value::as_str)
424	                        .map(|s| w.string(s))
425	                        .transpose()?;
426	                    if matches!(kind, BlockKind::Text | BlockKind::Tool) && i.text.is_none() {
427	                        i.issues.push(Issue::Shape);
428	                    }
429	                    if kind == BlockKind::Tool
430	                        && !b.and_then(|b| b.get("input")).is_some_and(Value::is_object)
431	                    {
432	                        i.issues.push(Issue::ToolJson);
433	                    }
434	                    state.open_blocks = state
435	                        .open_blocks
436	                        .checked_add(1)
437	                        .ok_or(Error::Limit("items"))?;
438	                    entry.insert(ActiveBlock {
439	                        kind,
440	                        stopped: false,
441	                        fragments: String::new(),
442	                        fragmented: false,
443	                    });
444	                } else {
445	                    i.issues.push(Issue::BlockIndex);
446	                }
447	            } else {
448	                i.issues.push(Issue::BlockIndex);
449	            }
450	        }
451	        Some("content_block_delta") => {
452	            if !state.started || state.delta {
453	                i.issues.push(Issue::Sequence);
454	            }
455	            let delta = value.get("delta");
456	            let (kind, key, want) = match delta.and_then(|d| d.get("type")).and_then(Value::as_str)
457	            {
458	                Some("text_delta") => (Kind::Text, "text", BlockKind::Text),
459	                Some("thinking_delta") => (Kind::Thinking, "thinking", BlockKind::Thinking),
460	                Some("signature_delta") => (Kind::Protocol, "signature", BlockKind::Thinking),
461	                Some("input_json_delta") => (Kind::ToolFragment, "partial_json", BlockKind::Tool),
462	                _ => (Kind::Unsupported, "", BlockKind::Unknown),
463	            };
464	            i.kind = kind;
465	            let text = delta.and_then(|d| d.get(key)).and_then(Value::as_str);
466	            i.text = text.map(|s| w.string(s)).transpose()?;
467	            if want == BlockKind::Unknown {
468	                if delta
469	                    .and_then(|d| d.get("type"))
470	                    .and_then(Value::as_str)
471	                    .is_none()
472	                {
473	                    i.kind = Kind::Malformed;
474	                    i.issues.push(Issue::Shape);
475	                } else {
476	                    i.issues.push(Issue::Unknown);
477	                }
478	            } else if text.is_none() {
479	                i.issues.push(Issue::Shape);
480	            }
481	            if let Some(b) = index.and_then(|n| state.blocks.get_mut(&n)) {
482	                if b.stopped {
483	                    i.issues.push(Issue::Sequence);
484	                }
485	                if b.kind != want {
486	                    i.issues.push(Issue::DeltaType);
487	                }
488	                if want == BlockKind::Tool && b.kind == want && !b.stopped {
489	                    if let Some(s) = text {
490	                        w.output(s.len())?;
491	                        b.fragments.push_str(s);
492	                        b.fragmented = true;
493	                    }
494	                }
495	            } else {
496	                i.issues.push(Issue::BlockIndex);
497	            }
498	        }
499	        Some("content_block_stop") => {
500	            if !state.started || state.delta {
501	                i.issues.push(Issue::Sequence);
502	            }
503	            if let Some(b) = index.and_then(|n| state.blocks.get_mut(&n)) {
504	                if b.stopped {
505	                    i.issues.push(Issue::Sequence);
506	                } else {
507	                    b.stopped = true;
508	                    state.open_blocks -= 1;
509	                    if b.fragmented
510	                        && !strict(b.fragments.as_bytes(), w)?.is_some_and(|v| v.is_object())
511	                    {
512	                        i.issues.push(Issue::ToolJson);
513	                    }
514	                }
515	            } else {
516	                i.issues.push(Issue::BlockIndex);
517	            }
518	        }
519	        Some("message_delta") => {
520	            if !value.get("delta").is_some_and(Value::is_object) {
521	                i.issues.push(Issue::Shape);
522	            }
523	            if !state.started || state.open_blocks != 0 {
524	                i.issues.push(Issue::Sequence);
525	            }
526	            state.delta = true;
527	        }
528	        Some("message_stop") => {
529	            if !state.started || !state.delta || state.open_blocks != 0 {
530	                i.issues.push(Issue::Sequence);
531	            }
532	            state.stopped = true;
533	        }
534	        Some("ping") => {}
535	        Some("error") => {
536	            i.kind = Kind::Error;
537	            state.invalid = true;
538	        }
539	        _ => {
540	            if typ.is_none() {
541	                i.kind = Kind::Malformed;
542	                i.issues.push(Issue::Shape);
543	            } else {
544	                i.kind = Kind::Unsupported;
545	                i.issues.push(Issue::Unknown);
546	            }
547	        }
548	    }
549	    if !i.issues.is_empty() {
550	        state.invalid = true;
551	    }
552	    i.event = Some(value);
553	    Ok(i)
554	}
555	fn sse(
556	    bytes: &[u8],
557	    doc: &mut Document,
558	    w: &mut Work,
559	    after_item: &mut impl FnMut(),
560	) -> Result<()> {
561	    if bytes.is_empty() {
562	        push(&mut doc.items, item(Kind::Truncated, 0..0), w)?;
563	        return Ok(());
564	    }
565	    let mut state = State::default();
566	    let mut start = 0;
567	    let mut pos = 0;
568	    let mut data = Vec::new();
569	    let mut name: Option<String> = None;
570	    let mut has_data = false;
571	    while pos < bytes.len() {
572	        w.check()?;
573	        let line_start = pos;
574	        while pos < bytes.len() && !matches!(bytes[pos], b'\r' | b'\n') {
575	            pos += 1;
576	            if pos.is_multiple_of(65536) {
577	                w.check()?;
578	            }
579	        }
580	        if pos == bytes.len() {
581	            w.scan(pos - line_start)?;
582	            break;
583	        }
584	        let line = &bytes[line_start..pos];
585	        if bytes[pos] == b'\r' && bytes.get(pos + 1) == Some(&b'\n') {
586	            pos += 2;
587	        } else {
588	            pos += 1;
589	        }
590	        w.scan(pos - line_start)?;
591	        if line.is_empty() {
592	            let mut i = if has_data {
593	                if data.last() == Some(&b'\n') {
594	                    data.pop();
595	                }
596	                match strict(&data, w)? {
597	                    Some(v) => event(v, name.as_deref(), start..pos, &mut state, w)?,
598	                    None => {
599	                        state.invalid = true;
600	                        item(Kind::Malformed, start..pos)
601	                    }
602	                }
603	            } else {
604	                item(Kind::Protocol, start..pos)
605	            };
606	            // Invalid UTF-8 in event names is never silently repaired.
607	            if name.as_deref() == Some("\0invalid-utf8") {
608	                i.issues.push(Issue::EventName);
609	                state.invalid = true;
610	            }
611	            push(&mut doc.items, i, w)?;
612	            after_item();
613	            start = pos;
614	            data.clear();
615	            name = None;
616	            has_data = false;
617	        } else if !line.starts_with(b":") {
618	            let (field, mut value) = match line.iter().position(|&b| b == b':') {
619	                Some(n) => (&line[..n], &line[n + 1..]),
620	                None => (line, &[][..]),
621	            };
622	            if value.first() == Some(&b' ') {
623	                value = &value[1..];
624	            }
625	            match field {
626	                b"data" => {
627	                    w.output(value.len() + 1)?;
628	                    data.extend_from_slice(value);
629	                    data.push(b'\n');
630	                    has_data = true;
631	                }
632	                b"event" => {
633	                    name = Some(w.string(std::str::from_utf8(value).unwrap_or("\0invalid-utf8"))?);
634	                }
635	                _ => {}
636	            }
637	        }
638	    }
639	    if start < bytes.len() {
640	        push(&mut doc.items, item(Kind::Truncated, start..bytes.len()), w)?;
641	        state.invalid = true;
642	        after_item();
643	    }
644	    doc.coherent_stop_observed = state.stopped && !state.invalid;
645	    Ok(())
646	}
647	pub fn interpret(bytes: &[u8], format: Format, limits: Limits) -> Result<Document> {
648	    interpret_observed(bytes, format, limits, || {})
649	}
650	fn interpret_observed(
651	    bytes: &[u8],
652	    format: Format,
653	    limits: Limits,
654	    mut after_item: impl FnMut(),
655	) -> Result<Document> {
656	    let mut w = Work::new(limits)?;
657	    if bytes.len() > w.limits.input_bytes {
658	        return Err(Error::Limit("input bytes"));
659	    }
660	    let mut doc = Document {
661	        format,
662	        json: None,
663	        items: vec![],
664	        coherent_stop_observed: false,
665	        scanned_bytes: 0,
666	        output_bytes: 0,
667	    };
668	    if format == Format::Sse {
669	        sse(bytes, &mut doc, &mut w, &mut after_item)?;
670	    } else {
671	        json_body(bytes, format, &mut doc, &mut w)?;
672	        after_item();
673	    }
674	    w.check()?;
675	    doc.scanned_bytes = w.scan;
676	    doc.output_bytes = w.output;
677	    Ok(doc)
678	}
679	/// Map one enclosing region to exact original input spans. Validate the full
680	/// contiguous stream and every duplicate source before returning any citations.
681	/// This checks byte correspondence only, never a signature or access grant.
682	pub fn map_region(
683	    stream: &Stream,
684	    inputs: &[Input<'_>],
685	    region: Range<usize>,
686	    limits: Limits,
687	) -> Result<Vec<SourceSpan>> {
688	    let mut w = Work::new(limits)?;
689	    let bytes = stream.contiguous.as_deref().ok_or(Error::Mapping)?;
690	    if bytes.len() > w.limits.input_bytes {
691	        return Err(Error::Limit("input bytes"));
692	    }
693	    if !stream.issues.is_empty()
694	        || stream
695	            .expected_bytes
696	            .is_some_and(|n| n != bytes.len() as u64)
697	        || region.start > region.end
698	        || region.end > bytes.len()
699	    {
700	        return Err(Error::Mapping);
701	    }
702	    let mut next = 0usize;
703	    let mut out = vec![];
704	    let mut group = None;
705	    for s in &stream.segments {
706	        w.item()?;
707	        if s.offset != next as u64 || s.sources.is_empty() {
708	            return Err(Error::Mapping);
709	        }
710	        let end = next.checked_add(s.length).ok_or(Error::Mapping)?;
711	        let piece = bytes.get(next..end).ok_or(Error::Mapping)?;
712	        let mut first_raw = None;
713	        for source in &s.sources {
714	            w.item()?;
715	            let original = match inputs.get(source.input).map(|i| i.payload) {
716	                Some(Payload::Available(b)) => b,
717	                _ => return Err(Error::Mapping),
718	            };
719	            w.scan(original.len())?;
720	            let frame = match decode::decode(original) {
721	                Ok(Decoded::Capture(f)) => f,
722	                _ => return Err(Error::Mapping),
723	            };
724	            if frame.body_span != source.bytes {
725	                return Err(Error::Mapping);
726	            }
727	            let (direction, offset) = match frame.header.event {
728	                Event::RequestChunk { offset } => (0, offset),
729	                Event::ResponseChunk { offset } => (1, offset),
730	                _ => return Err(Error::Mapping),
731	            };
732	            if offset != s.offset {
733	                return Err(Error::Mapping);
734	            }
735	            let input = &inputs[source.input];
736	            let identity = (
737	                input.scope,
738	                input.writer,
739	                frame.header.observer,
740	                frame.header.attempt,
741	                direction,
742	            );
743	            if let Some(expected) = &group {
744	                if expected != &identity {
745	                    return Err(Error::Mapping);
746	                }
747	            } else {
748	                group = Some(identity);
749	            }
750	            if let Some(expected) = first_raw {
751	                w.scan(original.len())?;
752	                if expected != original {
753	                    return Err(Error::Mapping);
754	                }
755	            } else {
756	                first_raw = Some(original);
757	            }
758	            let raw = original.get(source.bytes.clone()).ok_or(Error::Mapping)?;
759	            w.scan(raw.len())?;
760	            if raw != piece {
761	                return Err(Error::Mapping);
762	            }
763	            let a = next.max(region.start);
764	            let b = end.min(region.end);
765	            if a < b || (region.is_empty() && next <= a && a <= end && a == region.start) {
766	                if out.len() >= w.limits.citations {
767	                    return Err(Error::Limit("citations"));
768	                }
769	                out.push(SourceSpan {
770	                    input: source.input,
771	                    bytes: (source.bytes.start + a - next)..(source.bytes.start + b - next),
772	                });
773	            }
774	        }
775	        next = end;
776	    }
777	    if next != bytes.len() {
778	        return Err(Error::Mapping);
779	    }
780	    w.check()?;
781	    Ok(out)
782	}
783	#[cfg(test)]
784	mod tests {
785	    use super::*;
786	    #[test]
787	    fn cancellation_after_first_event_refuses_remaining_output() {
788	        let c = Arc::new(AtomicBool::new(false));
789	        let limits = Limits {
790	            input_bytes: 1000,
791	            items: 100,
792	            output_bytes: 1000,
793	            scan_bytes: 1000,
794	            citations: 100,
795	            duration: Duration::from_secs(1),
796	            cancelled: c.clone(),
797	        };
798	        let mut seen = 0;
799	        let result = interpret_observed(
800	            b"data: {\"type\":\"ping\"}\n\ndata: {\"type\":\"ping\"}\n\n",
801	            Format::Sse,
802	            limits,
803	            || {
804	                seen += 1;
805	                c.store(true, Ordering::Relaxed);
806	            },
807	        );
808	        assert_eq!(result.unwrap_err(), Error::Cancelled);
809	        assert_eq!(seen, 1);
810	    }
811	}
