1	//! Disposable assembly over an explicit, authorized occurrence selection.
2	//! Source indices retain caller-owned occurrence/proof/snapshot lineage. This
3	//! module neither checks grants nor discovers records, and claims no completeness.
4	use crate::{
5	    evidence_capture::{Event, Observer, Outcome},
6	    evidence_reconstruction::{self as decode, Decoded, Frame},
7	};
8	use std::{
9	    collections::BTreeMap,
10	    ops::Range,
11	    sync::{
12	        atomic::{AtomicBool, Ordering},
13	        Arc,
14	    },
15	    time::{Duration, Instant},
16	};
17	
18	pub const VERSION: &str = "kan-capture-assembly/1";
19	
20	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
21	pub enum Unavailable {
22	    Missing,
23	    Corrupt,
24	    Withheld,
25	}
26	#[derive(Clone, Copy)]
27	pub enum Payload<'a> {
28	    Available(&'a [u8]),
29	    Unavailable(Unavailable),
30	}
31	/// Identity comes from verified reader selection, never from captured JSON.
32	pub struct Input<'a> {
33	    pub scope: [u8; 32],
34	    pub writer: &'a str,
35	    pub payload: Payload<'a>,
36	}
37	#[derive(Debug)]
38	pub enum Observation<'a> {
39	    Capture(Frame<'a>),
40	    Opaque,
41	    Unsupported(decode::Unsupported),
42	    Malformed(decode::Error),
43	    Unavailable(Unavailable),
44	}
45	#[derive(Clone)]
46	pub struct Limits {
47	    pub occurrences: usize,
48	    /// Raw frame bytes plus caller-supplied writer bytes, counted per occurrence.
49	    pub input_bytes: u64,
50	    /// Decode, duplicate comparison and assembled copying work; not CPU time.
51	    pub scan_bytes: u64,
52	    pub assembled_bytes: u64,
53	    pub duration: Duration,
54	    pub cancelled: Arc<AtomicBool>,
55	}
56	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
57	pub enum Error {
58	    #[error("assembly budget exhausted: {0}")]
59	    Limit(&'static str),
60	    #[error("assembly cancelled")]
61	    Cancelled,
62	}
63	type Result<T> = std::result::Result<T, Error>;
64	
65	#[derive(Debug, Clone, PartialEq, Eq)]
66	pub struct SourceSpan {
67	    pub input: usize,
68	    /// Exact exclusive byte range within that input's decrypted frame.
69	    pub bytes: Range<usize>,
70	}
71	#[derive(Debug)]
72	pub struct Segment {
73	    pub offset: u64,
74	    pub length: usize,
75	    /// Exact duplicate frames share a segment, retaining every occurrence.
76	    pub sources: Vec<SourceSpan>,
77	}
78	#[derive(Debug, Clone, PartialEq, Eq)]
79	pub enum StreamIssue {
80	    OffsetOverflow { input: usize },
81	    Gap(Range<u64>),
82	    Overlap { input: usize },
83	    ConflictingExtents,
84	    BeyondExtent { input: usize },
85	    ChunkAfterEnd { input: usize },
86	    OrdinalConflict,
87	}
88	#[derive(Debug)]
89	pub struct Stream {
90	    pub segments: Vec<Segment>,
91	    /// Every request-end claim with its source. Responses have no extent claim.
92	    pub extents: Vec<(usize, u64)>,
93	    pub expected_bytes: Option<u64>,
94	    pub issues: Vec<StreamIssue>,
95	    /// A contiguous observed prefix only. Even Some(empty) is not a coverage
96	    /// certificate. None means absent data or contradictory/gapped segments.
97	    pub contiguous: Option<Vec<u8>>,
98	}
99	#[derive(Debug)]
100	pub struct Ordinal {
101	    pub value: u64,
102	    pub inputs: Vec<usize>,
103	    pub conflict: bool,
104	}
105	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
106	pub enum Terminal {
107	    Unknown,
108	    Claimed(Outcome),
109	    Conflicting,
110	}
111	#[derive(Debug)]
112	pub struct Group {
113	    pub scope: [u8; 32],
114	    pub writer: String,
115	    pub observer: Observer,
116	    pub attempt: String,
117	    pub ordinals: Vec<Ordinal>,
118	    /// No recognized capture at these ordinals; not proof of missing inputs.
119	    /// Unplaced unsupported/malformed/unavailable observations stay in Assembly.
120	    /// No invented trailing extent.
121	    pub ordinal_gaps: Vec<Range<u64>>,
122	    pub missing_start: bool,
123	    pub unexpected_starts: Vec<usize>,
124	    pub terminal: Terminal,
125	    pub events_after_terminal: bool,
126	    /// Observer claim only; not an exact count of lost remote records.
127	    pub unconfirmed_claim: bool,
128	    pub request: Stream,
129	    pub response: Stream,
130	}
131	#[derive(Debug)]
132	pub struct Assembly<'a> {
133	    /// Exactly one entry per input, in the same order. Keep caller lineage with it.
134	    pub observations: Vec<Observation<'a>>,
135	    pub groups: Vec<Group>,
136	    pub scanned_bytes: u64,
137	    pub assembled_bytes: u64,
138	}
139	struct Work {
140	    limits: Limits,
141	    deadline: Instant,
142	    scanned: u64,
143	    assembled: u64,
144	}
145	impl Work {
146	    fn check(&self) -> Result<()> {
147	        if self.limits.cancelled.load(Ordering::Relaxed) {
148	            return Err(Error::Cancelled);
149	        }
150	        if Instant::now() >= self.deadline {
151	            return Err(Error::Limit("duration"));
152	        }
153	        Ok(())
154	    }
155	    fn scan(&mut self, n: usize) -> Result<()> {
156	        self.check()?;
157	        self.scanned = self
158	            .scanned
159	            .checked_add(n as u64)
160	            .ok_or(Error::Limit("scan bytes"))?;
161	        if self.scanned > self.limits.scan_bytes {
162	            return Err(Error::Limit("scan bytes"));
163	        }
164	        Ok(())
165	    }
166	    fn copy(&mut self, n: usize) -> Result<()> {
167	        self.scan(n)?;
168	        self.assembled = self
169	            .assembled
170	            .checked_add(n as u64)
171	            .ok_or(Error::Limit("assembled bytes"))?;
172	        if self.assembled > self.limits.assembled_bytes {
173	            return Err(Error::Limit("assembled bytes"));
174	        }
175	        Ok(())
176	    }
177	}
178	fn frame<'s, 'a>(observations: &'s [Observation<'a>], i: usize) -> &'s Frame<'a> {
179	    match &observations[i] {
180	        Observation::Capture(f) => f,
181	        _ => unreachable!(),
182	    }
183	}
184	fn raw<'a>(input: &Input<'a>) -> &'a [u8] {
185	    match input.payload {
186	        Payload::Available(b) => b,
187	        _ => unreachable!(),
188	    }
189	}
190	fn identical(a: &[u8], b: &[u8], work: &mut Work) -> Result<bool> {
191	    if a.len() != b.len() {
192	        work.check()?;
193	        return Ok(false);
194	    }
195	    for (a, b) in a.chunks(65536).zip(b.chunks(65536)) {
196	        work.scan(a.len())?;
197	        if a != b {
198	            return Ok(false);
199	        }
200	    }
201	    Ok(true)
202	}
203	fn stream(
204	    ordinals: &[Ordinal],
205	    observations: &[Observation<'_>],
206	    request: bool,
207	    work: &mut Work,
208	) -> Result<Stream> {
209	    let mut out = Stream {
210	        segments: vec![],
211	        extents: vec![],
212	        expected_bytes: None,
213	        issues: vec![],
214	        contiguous: None,
215	    };
216	    for ordinal in ordinals {
217	        work.check()?;
218	        if ordinal.conflict {
219	            out.issues.push(StreamIssue::OrdinalConflict);
220	        }
221	        // Conflicting variants remain separate. Identical duplicates share only
222	        // their interpretation, never their occurrence identity.
223	        let variants = if ordinal.conflict {
224	            ordinal.inputs.as_slice()
225	        } else {
226	            &ordinal.inputs[..1]
227	        };
228	        for &i in variants {
229	            let f = frame(observations, i);
230	            if request {
231	                if let Event::RequestEnd { bytes } = f.header.event {
232	                    for &index in if ordinal.conflict {
233	                        std::slice::from_ref(&i)
234	                    } else {
235	                        &ordinal.inputs
236	                    } {
237	                        out.extents.push((index, bytes));
238	                    }
239	                }
240	            }
241	            let offset = match (&f.header.event, request) {
242	                (Event::RequestChunk { offset }, true)
243	                | (Event::ResponseChunk { offset }, false) => *offset,
244	                _ => continue,
245	            };
246	            let sources = if ordinal.conflict {
247	                std::slice::from_ref(&i)
248	            } else {
249	                &ordinal.inputs
250	            };
251	            out.segments.push(Segment {
252	                offset,
253	                length: f.body.len(),
254	                sources: sources
255	                    .iter()
256	                    .map(|&input| SourceSpan {
257	                        input,
258	                        bytes: frame(observations, input).body_span.clone(),
259	                    })
260	                    .collect(),
261	            });
262	        }
263	    }
264	    if let Some(&(_, n)) = out.extents.first() {
265	        if out.extents.iter().all(|&(_, x)| x == n) {
266	            out.expected_bytes = Some(n);
267	        } else {
268	            out.issues.push(StreamIssue::ConflictingExtents);
269	        }
270	    }
271	    out.segments.sort_by_key(|s| (s.offset, s.sources[0].input));
272	    work.check()?;
273	    let mut end = 0;
274	    let mut total = 0usize;
275	    let first_end = out
276	        .extents
277	        .iter()
278	        .map(|&(i, _)| frame(observations, i).header.ordinal)
279	        .min();
280	    for s in &out.segments {
281	        work.check()?;
282	        let input = s.sources[0].input;
283	        if first_end.is_some_and(|n| n < frame(observations, input).header.ordinal) {
284	            out.issues.push(StreamIssue::ChunkAfterEnd { input });
285	        }
286	        let Some(next) = s.offset.checked_add(s.length as u64) else {
287	            out.issues.push(StreamIssue::OffsetOverflow { input });
288	            continue;
289	        };
290	        if s.offset > end {
291	            out.issues.push(StreamIssue::Gap(end..s.offset));
292	        }
293	        // Empty frames at a covered offset contain no overlapping byte evidence.
294	        if s.length > 0 && s.offset < end {
295	            out.issues.push(StreamIssue::Overlap { input });
296	        }
297	        if out.expected_bytes.is_some_and(|extent| next > extent) {
298	            out.issues.push(StreamIssue::BeyondExtent { input });
299	        }
300	        end = end.max(next);
301	        total = total
302	            .checked_add(s.length)
303	            .ok_or(Error::Limit("assembled bytes"))?;
304	    }
305	    if let Some(n) = out.expected_bytes {
306	        if end < n {
307	            out.issues.push(StreamIssue::Gap(end..n));
308	        }
309	    }
310	    if out.issues.is_empty() && (!out.segments.is_empty() || out.expected_bytes == Some(0)) {
311	        work.copy(total)?;
312	        let mut bytes = Vec::with_capacity(total);
313	        for s in &out.segments {
314	            work.check()?;
315	            bytes.extend_from_slice(frame(observations, s.sources[0].input).body);
316	        }
317	        out.contiguous = Some(bytes);
318	    }
319	    Ok(out)
320	}
321	
322	/// Assemble the explicit selection or refuse the whole operation on a budget.
323	/// No serializer is provided: API consumers must preserve u64 coordinates.
324	pub fn assemble<'a>(inputs: &[Input<'a>], limits: Limits) -> Result<Assembly<'a>> {
325	    assemble_observed(inputs, limits, || {})
326	}
327	fn assemble_observed<'a>(
328	    inputs: &[Input<'a>],
329	    limits: Limits,
330	    mut after_decode: impl FnMut(),
331	) -> Result<Assembly<'a>> {
332	    if limits.duration.is_zero() || limits.duration > Duration::from_secs(3600) {
333	        return Err(Error::Limit("duration"));
334	    }
335	    let deadline = Instant::now()
336	        .checked_add(limits.duration)
337	        .ok_or(Error::Limit("duration"))?;
338	    let mut work = Work {
339	        limits,
340	        deadline,
341	        scanned: 0,
342	        assembled: 0,
343	    };
344	    work.check()?;
345	    if inputs.len() > work.limits.occurrences {
346	        return Err(Error::Limit("occurrences"));
347	    }
348	    let mut input_bytes = 0u64;
349	    // Preflight every encoded input before decoding/allocating derived state.
350	    for input in inputs {
351	        work.check()?;
352	        let bytes = match input.payload {
353	            Payload::Available(b) => b.len(),
354	            _ => 0,
355	        };
356	        input_bytes = input_bytes
357	            .checked_add(bytes as u64)
358	            .and_then(|n| n.checked_add(input.writer.len() as u64))
359	            .ok_or(Error::Limit("input bytes"))?;
360	        if input_bytes > work.limits.input_bytes {
361	            return Err(Error::Limit("input bytes"));
362	        }
363	    }
364	    let mut observations = Vec::with_capacity(inputs.len());
365	    for input in inputs {
366	        work.check()?;
367	        observations.push(match input.payload {
368	            Payload::Unavailable(reason) => Observation::Unavailable(reason),
369	            Payload::Available(bytes) => {
370	                work.scan(bytes.len())?;
371	                match decode::decode(bytes) {
372	                    Ok(Decoded::Capture(f)) => Observation::Capture(f),
373	                    Ok(Decoded::Opaque) => Observation::Opaque,
374	                    Ok(Decoded::Unsupported(r)) => Observation::Unsupported(r),
375	                    Err(e) => Observation::Malformed(e),
376	                }
377	            }
378	        });
379	        after_decode();
380	    }
381	    type Key<'a> = ([u8; 32], &'a str, u8, &'a str);
382	    let mut grouped: BTreeMap<Key<'_>, BTreeMap<u64, Vec<usize>>> = BTreeMap::new();
383	    for (i, observation) in observations.iter().enumerate() {
384	        work.check()?;
385	        if let Observation::Capture(f) = observation {
386	            let observer = match f.header.observer {
387	                Observer::Collector => 0,
388	                Observer::Gateway => 1,
389	            };
390	            grouped
391	                .entry((
392	                    inputs[i].scope,
393	                    inputs[i].writer,
394	                    observer,
395	                    &f.header.attempt,
396	                ))
397	                .or_default()
398	                .entry(f.header.ordinal)
399	                .or_default()
400	                .push(i);
401	        }
402	    }
403	    let mut groups = Vec::with_capacity(grouped.len());
404	    for ((scope, writer, observer, attempt), ordered) in grouped {
405	        let mut ordinals = Vec::with_capacity(ordered.len());
406	        let mut gaps = vec![];
407	        let mut next = Some(0);
408	        let mut starts = vec![];
409	        let mut terminals = vec![];
410	        let mut unconfirmed = false;
411	        for (value, indices) in ordered {
412	            work.check()?;
413	            if let Some(n) = next {
414	                if value > n {
415	                    gaps.push(n..value);
416	                }
417	            }
418	            next = value.checked_add(1);
419	            let mut conflict = false;
420	            for &i in &indices[1..] {
421	                if !identical(raw(&inputs[indices[0]]), raw(&inputs[i]), &mut work)? {
422	                    conflict = true;
423	                }
424	            }
425	            for &i in &indices {
426	                let f = frame(&observations, i);
427	                unconfirmed |= f.header.unconfirmed_before > 0;
428	            }
429	            let variants = if conflict {
430	                indices.as_slice()
431	            } else {
432	                &indices[..1]
433	            };
434	            for &i in variants {
435	                match frame(&observations, i).header.event {
436	                    Event::Started { .. } => starts.push(i),
437	                    Event::Terminal { outcome } => terminals.push((value, outcome)),
438	                    _ => {}
439	                }
440	            }
441	            ordinals.push(Ordinal {
442	                value,
443	                inputs: indices,
444	                conflict,
445	            });
446	        }
447	        let missing_start = !starts
448	            .iter()
449	            .any(|&i| frame(&observations, i).header.ordinal == 0);
450	        let unexpected_starts = starts
451	            .into_iter()
452	            .filter(|&i| frame(&observations, i).header.ordinal != 0)
453	            .collect();
454	        let terminal = match terminals.as_slice() {
455	            [] => Terminal::Unknown,
456	            [(n, outcome)] if !ordinals.iter().any(|o| o.value == *n && o.conflict) => {
457	                Terminal::Claimed(*outcome)
458	            }
459	            _ => Terminal::Conflicting,
460	        };
461	        let events_after_terminal = terminals
462	            .first()
463	            .is_some_and(|(n, _)| ordinals.last().is_some_and(|o| o.value > *n));
464	        let request = stream(&ordinals, &observations, true, &mut work)?;
465	        let response = stream(&ordinals, &observations, false, &mut work)?;
466	        groups.push(Group {
467	            scope,
468	            writer: writer.into(),
469	            observer: if observer == 0 {
470	                Observer::Collector
471	            } else {
472	                Observer::Gateway
473	            },
474	            attempt: attempt.into(),
475	            ordinals,
476	            ordinal_gaps: gaps,
477	            missing_start,
478	            unexpected_starts,
479	            terminal,
480	            events_after_terminal,
481	            unconfirmed_claim: unconfirmed,
482	            request,
483	            response,
484	        });
485	    }
486	    work.check()?;
487	    Ok(Assembly {
488	        observations,
489	        groups,
490	        scanned_bytes: work.scanned,
491	        assembled_bytes: work.assembled,
492	    })
493	}
494	
495	#[cfg(test)]
496	mod tests {
497	    use super::*;
498	    #[test]
499	    fn cancellation_after_decode_stops_before_the_next_input() {
500	        let cancelled = Arc::new(AtomicBool::new(false));
501	        let limits = Limits {
502	            occurrences: 10,
503	            input_bytes: 100,
504	            scan_bytes: 100,
505	            assembled_bytes: 100,
506	            duration: Duration::from_secs(10),
507	            cancelled: cancelled.clone(),
508	        };
509	        let inputs = [
510	            Input {
511	                scope: [0; 32],
512	                writer: "w",
513	                payload: Payload::Available(b"opaque"),
514	            },
515	            Input {
516	                scope: [0; 32],
517	                writer: "w",
518	                payload: Payload::Available(b"second"),
519	            },
520	        ];
521	        let mut decoded = 0;
522	        let result = assemble_observed(&inputs, limits, || {
523	            decoded += 1;
524	            cancelled.store(true, Ordering::Relaxed);
525	        });
526	        assert_eq!(result.unwrap_err(), Error::Cancelled);
527	        assert_eq!(decoded, 1);
528	    }
529	}
