fn tiles(d: &p::Document, len: usize) {
    let mut prev = 0;
    for i in &d.items {
        assert_eq!(i.region.start, prev, "regions must tile");
        assert!(i.region.end >= i.region.start && i.region.end <= len);
        prev = i.region.end;
